-- Source and independent-solution verification; no historical scores changed.
-- Before-images are retained in audit_log; rows in active exams are deferred.
DO $review$
DECLARE v jsonb; q public.questions%rowtype; k public.question_keys%rowtype; a jsonb; f jsonb; patch jsonb;
BEGIN
 FOR v IN SELECT value FROM jsonb_array_elements($payload$[{"id": "b515a6ed-1c6f-5848-b2b4-12c02a5d4524", "source": "New exams_251110_.pdf, physical page 101", "review_note": "Complete original exam page 101 visually checked; answer independently solved and all choices checked.  Existing canonical question verified against recovered original.", "correct": "D", "explanation": "The vertex is (1,0), and the symmetry axis is x=1. The graph passes through (0,−1), giving y=−(x−1)²=−x²+2x−1. Thus I and III are true.", "release": true, "before": {"stem": "Use the graph below. Which of the following statement(s) is/are true regarding the graph? I. The coordinates of the vertex of the parabola are (1, 0). II. The axis of symmetry is at x = −1. III. The equation of the parabola is y = −x² + 2x − 1.", "choices": [{"key": "A", "text": "I only"}, {"key": "B", "text": "II only"}, {"key": "C", "text": "I and II only"}, {"key": "D", "text": "I and III only"}], "correct": "D", "explanation": "The graph has vertex (1, 0), axis x = 1, and equation y = −(x − 1)² = −x² + 2x − 1. Thus I and III are true."}, "fields": {"assets_patch": {"figure": "data:image/jpeg;base64,", "source_verification_date": "2026-09-29", "figure_required": false}}}, {"id": "0f808148-2950-5c6c-b3de-637ce88d6c56", "source": "New exams_251110_.pdf, physical page 101", "review_note": "Complete original exam page 101 visually checked; answer independently solved and all choices checked.  Existing canonical question verified against recovered original.", "correct": "B", "explanation": "The vertex is (1,0). At the vertex of this vertical parabola the tangent is horizontal, so its equation is y=0.", "release": true, "before": {"stem": "What is the equation of the tangent to this parabola at the vertex?", "choices": [{"key": "A", "text": "x = 0"}, {"key": "B", "text": "y = 0"}, {"key": "C", "text": "y = x"}, {"key": "D", "text": "y = −x"}], "correct": "B", "explanation": "A horizontal line meets this downward parabola exactly once only at its vertex, whose y-coordinate is 0."}, "fields": {"assets_patch": {"source_verification_date": "2026-09-29", "figure_required": false}}, "figure_from_id": "b515a6ed-1c6f-5848-b2b4-12c02a5d4524"}, {"id": "5c9392df-6634-5759-b87a-1dd771ee5b1e", "source": "New exams_251110_.pdf, physical page 79", "review_note": "Complete original exam page 79 visually checked; answer independently solved and all choices checked. Both percentages and all answer choices read from complete original bar chart; salary label is 20%, not an estimate from bar height. Existing canonical question verified against recovered original.", "correct": "A", "explanation": "The full budget is 200000/0.125=$1600000. Salaries receive 20% of that, or $320000.", "release": true, "before": {"stem": "The adjacent bar graph represents the percentage of money spent by a company on different sectors last year (Infrastructure 20%, Transport 12.5%, Advertisement 15%, Taxes 10%, Research and Development 5%, Salary 20%, Interest on Loans 17.5%). If $200,000 were spent on the transport sector, what was the budget used for salaries?", "choices": [{"key": "A", "text": "$320,000"}, {"key": "B", "text": "$340,000"}, {"key": "C", "text": "$360,000"}, {"key": "D", "text": "$370,000"}], "correct": "A", "explanation": "Transport is 12.5% and salaries 20% of the same budget. Salary spending is 200,000 × 20/12.5 = $320,000."}, "fields": {"assets_patch": {"source_verification_date": "2026-09-29", "figure_required": false}}}, {"id": "36278e2c-23dd-52c9-a36e-9a438161cbc7", "source": "New exams_251110_.pdf, physical page 111", "review_note": "Complete original exam page 111 visually checked; answer independently solved and all choices checked.  Existing canonical question verified against recovered original.", "correct": "C", "explanation": "Honda is the dashed series: 800 cars in 2010 and 700 in 2015. The decline is (800−700)/800×100=12.5%.", "release": true, "before": {"stem": "Questions 45 and 46: A graph shows the number of new cars of two brands, Hyundai (solid) and Honda (dashed), bought by citizens in country X during years 2010–2019. — According to the graph, how much was the percentage decrease of buying a new Honda from 2010 to 2015?", "choices": [{"key": "A", "text": "5.5"}, {"key": "B", "text": "10.5"}, {"key": "C", "text": "12.5"}, {"key": "D", "text": "20.5"}], "correct": "C", "explanation": "Honda decreases from 800 in 2010 to 700 in 2015. The percentage decrease is 100(800 − 700)/800 = 12.5%."}, "fields": {"assets_patch": {"figure": "data:image/jpeg;base64,", "source_verification_date": "2026-09-29", "figure_required": false}}}, {"id": "bccff428-b913-5ac1-bee2-261c2e9dc26d", "source": "New exams_251110_.pdf, physical page 111", "review_note": "Separate complete question recovered from original exam page 111; independently solved. Existing canonical DAP 026 verified.", "correct": "B", "explanation": "The first tie is in 2012 at 900 cars. Hyundai first exceeds Honda by 50 cars in 2016 (800 versus 750). Thus 2016−2012=4 years.", "release": true, "before": {"stem": "The graph shows new Hyundai cars (solid line) and Honda cars (dashed line) bought in country X. After the first tie between the number of cars bought of the two brands, how many years did it take Hyundai to sell 50 more cars than Honda in country X?", "choices": [{"key": "A", "text": "1"}, {"key": "B", "text": "4"}, {"key": "C", "text": "6"}, {"key": "D", "text": "7"}], "correct": "B", "explanation": "The first tie is in 2012. In 2016 Hyundai is at 800 and Honda at 750, a difference of 50. This is four years later."}, "fields": {"assets_patch": {"verification_source": "New exams_251110_.pdf, physical page 111", "source_verification_date": "2026-09-29", "figure_required": false}}, "figure_from_id": "36278e2c-23dd-52c9-a36e-9a438161cbc7"}]$payload$::jsonb) LOOP
  SELECT * INTO q FROM public.questions WHERE id=(v->>'id')::uuid FOR UPDATE;
  SELECT * INTO k FROM public.question_keys WHERE question_id=q.id FOR UPDATE;
  IF q.id IS NULL OR k.question_id IS NULL THEN RAISE EXCEPTION 'Missing question/key %',v->>'id'; END IF;
  IF EXISTS(SELECT 1 FROM public.audit_log WHERE action='question_review_20260929' AND target_id=q.id::text) THEN CONTINUE; END IF;
  IF q.stem IS DISTINCT FROM v->'before'->>'stem' OR q.choices IS DISTINCT FROM v->'before'->'choices'
     OR k.correct IS DISTINCT FROM v->'before'->'correct' OR k.explanation IS DISTINCT FROM v->'before'->>'explanation' THEN
    RAISE EXCEPTION 'Concurrent question change %',q.id;
  END IF;
  IF EXISTS(SELECT 1 FROM public.exams e JOIN public.attempts t ON t.exam_id=e.id
      WHERE q.id=ANY(e.question_ids) AND t.status='in_progress' AND t.deadline_at>now()) THEN
    INSERT INTO public.audit_log(action,target_type,target_id,meta) VALUES('question_review_deferred_20260929','question',q.id::text,jsonb_build_object('reason','Active exam','proposed',v));
    CONTINUE;
  END IF;
  INSERT INTO public.audit_log(action,target_type,target_id,meta)
  VALUES('question_review_20260929','question',q.id::text,jsonb_build_object('before_question',to_jsonb(q),'before_key',to_jsonb(k),'verification',v-'before'));
  a=coalesce(q.assets,'{}'::jsonb); patch=coalesce(v->'fields','{}'::jsonb);
  IF v ? 'figure_from_id' THEN
   SELECT assets->'figure' INTO f FROM public.questions WHERE id=(v->>'figure_from_id')::uuid;
   IF f IS NULL THEN RAISE EXCEPTION 'Missing verified figure for %',q.id; END IF;
   a=(a-'figure_required')||jsonb_build_object('figure',f,'figure_verified_source',v->>'figure_from_id');
  END IF;
  a=a||coalesce(patch->'assets_patch','{}'::jsonb)||jsonb_build_object(
    'answer_review','2026-09-29-independent-solution-and-source-check','verification_source',v->>'source',
    'verification_note',v->>'review_note','content_audit','2026-09-29-all-bank-structural-audit');
  IF coalesce((v->>'release')::boolean,false) THEN
   a=(a-'release_hold_reason')||jsonb_build_object('verified_release','2026-09-29-independent-solution-and-source-check');
  ELSIF v ? 'duplicate_of' THEN
   a=a||jsonb_build_object('release_hold_reason','Duplicate of reviewed question','duplicate_of',v->>'duplicate_of');
  END IF;
  UPDATE public.questions SET stem=coalesce(patch->>'stem',q.stem),choices=coalesce(patch->'choices',q.choices),
   topic=coalesce(patch->>'topic',q.topic),type=coalesce(patch->>'type',q.type),assets=a WHERE id=q.id;
  UPDATE public.question_keys SET correct=coalesce(v->'correct',k.correct),explanation=coalesce(v->>'explanation',k.explanation) WHERE question_id=q.id;
  IF v->>'source_question_id' IS NOT NULL THEN
   INSERT INTO public.audit_log(action,target_type,target_id,meta)
   SELECT 'staged_question_review_20260929','question_bank',b.question_id,jsonb_build_object('before',to_jsonb(b)) FROM public.question_bank b WHERE b.question_id=v->>'source_question_id';
   UPDATE public.question_bank SET stem_text=coalesce(patch->>'stem',q.stem),choices=coalesce(patch->'choices',q.choices),
    answer_key=coalesce(v->'correct',k.correct)#>>'{}',answer_explanation=coalesce(v->>'explanation',k.explanation),
    answer_key_status='independently_verified',needs_review=false,review_reasons=jsonb_build_array(v->>'review_note')
   WHERE question_id=v->>'source_question_id' AND coalesce((v->>'release')::boolean,false);
  END IF;
 END LOOP;
END;
$review$;
SELECT jsonb_build_object('applied',(SELECT count(*) FROM public.audit_log WHERE action='question_review_20260929'),
 'deferred',(SELECT count(*) FROM public.audit_log WHERE action='question_review_deferred_20260929')) AS result;
